const fs = require('fs');

const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
let idx = 0;

const n = parseInt(input[idx++]);
const k = parseInt(input[idx++]);

const res = [];

function solve(n, k) {
    if (n === 1) {
        return;
    }
    if (k === 1) {
        res.push(n);
        return;
    }
    const limit = Math.floor(Math.sqrt(n)) + 1;
    for (let i = 2; i <= limit; i++) {
        if (n % i === 0) {
            res.push(i);
            solve(n / i, k - 1);
            return;
        }
    }
}

solve(n, k);

if (res.length === 0 || res.length !== k) {
    console.log(-1);
    process.exit(0);
}

let check = 1;
for (const el of res) {
    check *= el;
}
if (check !== n) {
    console.log(-1);
    process.exit(0);
}

console.log(res.join(' '));

